[{"order":1,"type":"heading","text":"JavaScript Arrays: Methods and Iteration"},{"order":2,"type":"paragraph","text":"Arrays are fundamental data structures in JavaScript, used to store collections of items. This tutorial explores common array methods and techniques for iterating through arrays."},{"order":3,"type":"subheading","text":"Array Methods"},{"order":4,"type":"paragraph","text":"JavaScript provides a rich set of built-in methods for manipulating arrays. Here are some of the most frequently used:"},{"order":5,"type":"bullet_point","text":"`push()`: Adds one or more elements to the end of an array and returns the new length of the array."},{"order":6,"type":"code","text":"const myArray = [1, 2, 3];
myArray.push(4, 5);
console.log(myArray); // Output: [1, 2, 3, 4, 5]"},{"order":7,"type":"bullet_point","text":"`pop()`: Removes the last element from an array and returns that element."},{"order":8,"type":"code","text":"const myArray = [1, 2, 3];
const lastElement = myArray.pop();
console.log(myArray); // Output: [1, 2]
console.log(lastElement); // Output: 3"},{"order":9,"type":"bullet_point","text":"`shift()`: Removes the first element from an array and returns that element."},{"order":10,"type":"code","text":"const myArray = [1, 2, 3];
const firstElement = myArray.shift();
console.log(myArray); // Output: [2, 3]
console.log(firstElement); // Output: 1"},{"order":11,"type":"bullet_point","text":"`unshift()`: Adds one or more elements to the beginning of an array and returns the new length of the array."},{"order":12,"type":"code","text":"const myArray = [1, 2, 3];
myArray.unshift(0);
console.log(myArray); // Output: [0, 1, 2, 3]"},{"order":13,"type":"bullet_point","text":"`splice()`: Changes the contents of an array by removing or replacing existing elements and/or adding new elements in place."},{"order":14,"type":"code","text":"const myArray = [1, 2, 3, 4, 5];
myArray.splice(2, 1, 'a', 'b'); // Remove 1 element at index 2, and insert 'a' and 'b'
console.log(myArray); // Output: [1, 2, 'a', 'b', 4, 5]"},{"order":15,"type":"bullet_point","text":"`slice()`: Returns a shallow copy of a portion of an array into a new array object selected from `start` to `end` (`end` not included) where `start` and `end` represent the index of items in that array. The original array will not be modified."},{"order":16,"type":"code","text":"const myArray = [1, 2, 3, 4, 5];
const newArray = myArray.slice(1, 4);
console.log(newArray); // Output: [2, 3, 4]
console.log(myArray); // Output: [1, 2, 3, 4, 5]"},{"order":17,"type":"bullet_point","text":"`concat()`: Returns a new array consisting of the array on which it is called, joined with other array(s) and/or value(s)."},{"order":18,"type":"code","text":"const myArray = [1, 2];
const newArray = myArray.concat([3, 4], 5);
console.log(newArray); // Output: [1, 2, 3, 4, 5]"},{"order":19,"type":"bullet_point","text":"`indexOf()`: Returns the first index at which a given element can be found in the array, or -1 if it is not present."},{"order":20,"type":"code","text":"const myArray = [1, 2, 3, 4, 5];
const index = myArray.indexOf(3);
console.log(index); // Output: 2"},{"order":21,"type":"bullet_point","text":"`includes()`: Determines whether an array includes a certain element, returning `true` or `false` as appropriate."},{"order":22,"type":"code","text":"const myArray = [1, 2, 3, 4, 5];
const includesThree = myArray.includes(3);
console.log(includesThree); // Output: true"},{"order":23,"type":"subheading","text":"Array Iteration"},{"order":24,"type":"paragraph","text":"Iterating through arrays is a common task. JavaScript offers several ways to achieve this:"},{"order":25,"type":"bullet_point","text":"`for` loop: The traditional `for` loop provides explicit control over the iteration process."},{"order":26,"type":"code","text":"const myArray = [1, 2, 3, 4, 5];
for (let i = 0; i < myArray.length; i++) {
  console.log(myArray[i]);
}"},{"order":27,"type":"bullet_point","text":"`forEach()`: Executes a provided function once for each array element."},{"order":28,"type":"code","text":"const myArray = [1, 2, 3, 4, 5];
myArray.forEach(function(element) {
  console.log(element);
});"},{"order":29,"type":"bullet_point","text":"`map()`: Creates a new array with the results of calling a provided function on every element in the calling array."},{"order":30,"type":"code","text":"const myArray = [1, 2, 3, 4, 5];
const newArray = myArray.map(function(element) {
  return element * 2;
});
console.log(newArray); // Output: [2, 4, 6, 8, 10]"},{"order":31,"type":"bullet_point","text":"`filter()`: Creates a new array with all elements that pass the test implemented by the provided function."},{"order":32,"type":"code","text":"const myArray = [1, 2, 3, 4, 5];
const newArray = myArray.filter(function(element) {
  return element > 2;
});
console.log(newArray); // Output: [3, 4, 5]"},{"order":33,"type":"bullet_point","text":"`reduce()`: Executes a reducer function (that you provide) on each element of the array, resulting in a single output value."},{"order":34,"type":"code","text":"const myArray = [1, 2, 3, 4, 5];
const sum = myArray.reduce(function(accumulator, currentValue) {
  return accumulator + currentValue;
}, 0);
console.log(sum); // Output: 15"},{"order":35,"type":"bullet_point","text":"`for...of` loop: Provides a concise way to iterate over the values of an iterable object, including arrays."},{"order":36,"type":"code","text":"const myArray = [1, 2, 3, 4, 5];
for (const element of myArray) {
  console.log(element);
}"},{"order":37,"type":"paragraph","text":"Choosing the right iteration method depends on the specific task. `forEach` is suitable for simple iteration, while `map`, `filter`, and `reduce` are useful for transforming and aggregating array data. The `for` and `for...of` loops offer more control over the iteration process."}]
